WITH web_events_by_session AS (SELECT session_id, COUNT(duration_sec) AS duration_sec_count, MIN(event_time) AS first_event_time FROM web_events WHERE event_type = 'click' GROUP BY session_id) SELECT s.id, s.device, s.started_at, webs.duration_sec_count, webs.first_event_time FROM sessions s JOIN web_events_by_session webs ON s.id = webs.session_id ORDER BY webs.duration_sec_count DESC
